verify.cmd:
node -e 'const fs=require("node:fs"),dir="supabase/migrations";
const declaration=/create\s+(?:or\s+replace\s+)?function\s+(?:public\.)?hunt_claim_apply\s*\(/gi;
let body="";
for(const file of fs.readdirSync(dir).filter(f=>/^\d{14}_.*\.sql$/.test(f)&&f.slice(0,14)>="20270346037000").sort()){
  const sql=fs.readFileSync(dir+"/"+file,"utf8");
  const matches=[...sql.matchAll(declaration)];
  if(matches.length)body=sql.slice(matches.at(-1).index);
}
const claimInserts=[...body.matchAll(/\binsert\s+into\s+(?:public\.)?hunt_claims\b[^;]+;/gi)];
const holds=claimInserts.some(match=>/\b(?:state|status)\b/i.test(match[0])&&/\bneeds_review\b/i.test(match[0]));
const sqlTests="supabase/tests";
const covered=fs.readdirSync(sqlTests).filter(f=>f.includes("hunt")&&f.endsWith(".sql")).some(f=>{
  const test=fs.readFileSync(sqlTests+"/"+f,"utf8");
  return /\bhunt_claim_apply\s*\(/i.test(test)&&/\bneeds_review\b/i.test(test)&&/\bhunt_progress\b/i.test(test);
});
process.exit(holds&&covered&&/\bassurance_too_low\b/i.test(body)?0:1);'
